-- Generated by scripts/build_compiled.py from src/fraudrules/rules/foreign-agent/fa-005-repeated-round-amounts.yaml. Do not edit.
-- FA-005 MSB sends repeated round-dollar wires abroad
SELECT 'FA-005' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 2592000
WHERE (a.direction = 'out' AND a.channel = 'wire' AND a.counterparty_country <> 'us' AND a.round_amount = 1 AND (a.directing_agent_id IS NOT NULL OR a.customer_segment = 'msb')) AND (b.direction = 'out' AND b.channel = 'wire' AND b.counterparty_country <> 'us' AND b.round_amount = 1 AND (b.directing_agent_id IS NOT NULL OR b.customer_segment = 'msb'))
GROUP BY a.id
HAVING COUNT(*) >= 4;
